// Lesson 4's small examples. Numeric test results are generated by demo.py;
// round-boundary boards come from Lesson 3's shared deterministic trace.
(function () {
  if (window.__l4LessonInit) return;
  window.__l4LessonInit = true;
  const L = window.L2, D = window.L3, E = window.L4_EVIDENCE;
  const text = (g, s, x, y, o = {}) => L.text(g, s, x, y, { size: 26, ...o });
  const line = (g, x1, y1, x2, y2, color = L.WIRE) =>
    L.el('line', { x1, y1, x2, y2, stroke: color, 'stroke-width': 1.6 }, g);
  const arrow = (g, x1, y, x2, color = L.WIRE) => {
    line(g, x1, y, x2, y, color);
    L.el('path', { d: 'M ' + (x2 - 6) + ' ' + (y - 5) + ' l 6 5 l -6 5', fill: 'none', stroke: color, 'stroke-width': 1.6 }, g);
  };
  const box = (g, s, x, y, w = 130, color = L.BLUE) => {
    L.el('rect', { x, y, width: w, height: 46, rx: 7, fill: '#fff', stroke: color, 'stroke-width': 1.7 }, g);
    text(g, s, x + w / 2, y + 23, { fill: color, weight: 700 });
  };
  const pair = (g, colors, x, y) => {
    L.el('rect', { x: x - 47, y: y - 32, width: 148, height: 64, rx: 8, fill: '#efe6d3', stroke: L.WOODLINE }, g);
    colors.forEach((c, i) => L.stone(g, x + i * 55, y, 20, c + 1));
  };
  const smallBoard = colors => [colors[0] + 1, colors[1] + 1, 0, 0, 0, 0, 0, 0, 0];
  const scenes = {
    mirror(g) {
    text(g, 'A: forward', 60, 28, { anchor: 'start', weight: 700 });
    text(g, 'A†: backward', 60, 142, { anchor: 'start', fill: L.BLUE, weight: 700 });
    [['prepare', 'round 1', 'round 2', 'payoff'], ['payoff†', 'round 2†', 'round 1†', 'prepare†']].forEach((row,j)=>{
      row.forEach((s,i)=>{
        const x=60+i*175,y=58+j*114;
        box(g,s,x,y,125,j?L.BLUE:L.INK);
        if(i<3)arrow(g,x+130,y+23,x+168);
      });
    });
  },
    objectives(g) {
    // three questions about Lesson 3's rollout circuit, each naming its
    // subject: the inverse, the scratch qubits, the checks that run.  The
    // note says whose circuit they are about.
    ['Undo: what must the inverse still read?','Scratch: when can it go back to zero?','Checks: does the circuit play the right game?'].forEach((s,i)=>{
      const y=66+i*88;
      L.el('circle',{cx:60,cy:y,r:22,fill:L.BLUE},g);
      text(g,String(i+1),60,y,{fill:'#fff',weight:700,size:26});
      text(g,s,100,y,{anchor:'start',size:26,weight:700});
    });
  },
    boards(g) {
    [D.rounds[0].start,D.rounds[0].after,D.rounds[1].after].forEach((board,i)=>{
      const x=30+i*250;
      text(g,['initial','round 1','round 2'][i],x+95,28,{weight:700,size:28});
      L.board(g,{N:3,size:190,x,y:65,board});
      if(i<2)arrow(g,x+202,160,x+237);
    });
  },
    predict(g) {
    text(g,'dice: 0, 3',170,30,{weight:700,size:28});
    L.board(g,{N:3,size:200,x:70,y:65,board:smallBoard(E.event.initial)});
    text(g,'die < 4 − friends',515,85,{size:30,weight:700});
    text(g,'cell 0 → White',515,165,{size:28,fill:L.BLUE});
    text(g,'cell 1 → ?',515,235,{size:36,weight:700});
  },
    inplace(g) {
    [
      {x:35,title:'Old colors',color:L.GREEN,colors:E.event.expected,rule:'3 < 4: flip'},
      {x:415,title:'Updated colors',color:L.RED,colors:E.event.in_place.slice(0,2),rule:'3 ≥ 3: stay'}
    ].forEach(p=>{
      text(g,p.title,p.x+155,30,{weight:700,fill:p.color,size:28});
      L.board(g,{N:3,size:175,x:p.x+67.5,y:65,board:smallBoard(p.colors)});
      text(g,p.rule,p.x+155,277,{size:30,fill:p.color,weight:700});
    });
  },
    stranded(g) {
    [['compare',[0,0],'0 ⊕ 1 = 1',L.BLUE],
     ['flip',[1,0],'work = 1',L.ORANGE],
     ['uncompute',E.stranded.final.slice(0,2),'1 ⊕ 0 = '+E.stranded.final[2],L.RED]
    ].forEach(([title,colors,label,color],i)=>{
      const x=130+i*250;
      text(g,title,x,40,{weight:700,fill:color,size:28});
      pair(g,colors,x-27,135);
      text(g,label,x,230,{mono:true,weight:700,fill:color,size:26});
      if(i<2)arrow(g,x+87,135,x+155);
    });
  },
    dirty(g) {
    const empties=D.scanBoard.map((v,i)=>v?-1:i).filter(i=>i>=0);
    text(g,'rank = 2',380,32,{weight:700,size:32});
    [['cell',empties,L.INK],['clean',empties.map((_,i)=>i),L.GREEN],['dirty',empties.map((_,i)=>i+1),L.RED]].forEach(([label,values,color],row)=>{
      const y=105+row*70;
      text(g,label,170,y,{anchor:'end',fill:color,weight:700,size:28});
      values.forEach((value,i)=>{
        const x=240+i*68,match=row>0&&value===D.rank;
        if(match)L.el('rect',{x:x-25,y:y-25,width:50,height:50,rx:6,fill:color},g);
        text(g,String(value),x,y,{mono:true,size:30,fill:match?'#fff':color});
      });
    });
  },
    payoff(g) {
    const ys=[65,145,235];
    ['board','work','payoff'].forEach((s,i)=>{
      text(g,s,130,ys[i],{anchor:'end',size:26});
      line(g,150,ys[i],730,ys[i]);
      if(i)text(g,'0',175,ys[i]-24,{size:26});
    });
    [230,530].forEach((x,i)=>{
      L.el('rect',{x,y:35,width:110,height:140,rx:8,fill:'#fff',stroke:L.BLUE,'stroke-width':1.7},g);
      text(g,i?'W†':'W',x+55,105,{size:36,fill:L.BLUE,weight:700});
    });
    line(g,425,145,425,235,L.INK);
    L.el('circle',{cx:425,cy:145,r:6,fill:L.INK},g);
    L.el('circle',{cx:425,cy:235,r:15,fill:'#fff',stroke:L.INK,'stroke-width':1.8},g);
    line(g,414,235,436,235,L.INK);line(g,425,224,425,246,L.INK);
    text(g,'win',425,116,{size:26});
    text(g,'0',710,121,{fill:L.GREEN,weight:700,size:30});
    text(g,'f(board)',675,274,{fill:L.GREEN,weight:700,size:28});
  },
    tests(g) {
    [['Rules',E.event.basis_cases+'/4 inputs'],
     ['Phases',E.event.coherent_amplitudes_match?'matched':'FAILED'],
     ['Inverse',E.event.correct_roundtrip?'passed':'FAILED']
    ].forEach(([title,result],i)=>{
      const y=52+i*92;
      text(g,title,90,y,{anchor:'start',weight:700,size:32});
      box(g,result,510,y-23,190,L.GREEN);
    });
  },
    roundtrip(g) {
    [['input',E.event.initial,'work = 0',L.INK],
     ['in place',E.event.in_place.slice(0,2),'work = '+E.event.in_place[2],L.RED],
     ['inverse',E.event.initial,'restored',L.GREEN]
    ].forEach(([label,colors,sub,color],i)=>{
      const x=130+250*i;
      text(g,label,x,40,{size:28,weight:700,fill:color});
      pair(g,colors,x-27,135);
      text(g,sub,x,230,{fill:color,size:26});
      if(i<2)arrow(g,x+87,135,x+155);
    });
  },
    iterate(g) {
    text(g,'|0…0⟩',50,106,{mono:true,size:26});
    box(g,'A',110,83,75,L.INK);
    arrow(g,190,106,220);
    L.el('rect',{x:232,y:54,width:470,height:150,rx:12,fill:'none',stroke:L.BLUE,'stroke-width':1.6,'stroke-dasharray':'5 5'},g);
    ['Sgood','A†','S₀','A'].forEach((s,i)=>{
      const x=249+113*i;
      box(g,s,x,83,91,i%2?L.BLUE:L.PURPLE);
      if(i<3)arrow(g,x+95,106,x+108);
    });
    text(g,'once',147,175,{size:26});
    text(g,'repeat Q',467,174,{size:30,weight:700,fill:L.BLUE});
  },
    phase(g) {
    const result=L.el('g',{class:'step'},g);
    [['A → A†',E.payoff.plain_inverse_zero_probability,L.GREEN],
     ['A → Z → A†',E.payoff.marked_inverse_zero_probability,L.BLUE]
    ].forEach(([chain,p,color],i)=>{
      const x=190+380*i;
      text(g,chain,x,48,{size:32,weight:700,fill:color});
      text(result,p===1?'1':'¼',x,218,{size:68,weight:700,fill:color});
    });
    text(g,'P(all zero)?',380,130,{size:32});
  },
    checklist(g) {
    ['Right game?','Original inputs kept?','Scratch back to zero?','Complete A?','Rules, phases, inverse tested?'].forEach((s,i)=>{
      const y=38+i*52;
      L.el('circle',{cx:65,cy:y,r:17,fill:'#fff',stroke:L.BLUE,'stroke-width':1.6},g);
      text(g,String(i+1),65,y,{size:24,weight:700,fill:L.BLUE});
      text(g,s,110,y,{anchor:'start',size:30,weight:500});
    });
  }
  };
  document.querySelectorAll('svg.l4-demo').forEach(svg => {
    const name = svg.dataset.scene;
    svg.setAttribute('role', 'img');
    const title = L.el('title', {}, svg);
    title.textContent = svg.closest('.slide')?.querySelector('h2')?.textContent || name;
    const draw = scenes[name];
    if (!draw) throw new Error('Unknown Lesson 4 scene: ' + name);
    draw(L.el('g', {}, svg));
  });
  // A former optional Life detour is now folded into the Sway counterexample.
  if (location.hash === '#life') location.replace('#read-flipped');
})();
